1	// src/lib/plattform/backend/eg.js
2	//
3	// Fassade des Moduls Energiegemeinschaften (ElWG §§ 65–72). EINE Schnittstelle für alle Arbeitspakete; jedes Paket
4	// implementiert seine Operationen in eigenen Dateien (Demo und Frappe mit identischen Signaturen):
5	//   WP1 Stamm      backend/demo/eg-stamm.js      · backend/frappe/eg-stamm.js      (Frappe: plattform/api/eg_stamm.py)
6	//   WP2 EDA        backend/demo/eg-eda.js        · backend/frappe/eg-eda.js        (plattform/api/eg_eda.py)
7	//   WP3 Energie    backend/demo/eg-energie.js    · backend/frappe/eg-energie.js    (plattform/api/eg_energie.py)
8	//   WP4 Abrechnung backend/demo/eg-abrechnung.js · backend/frappe/eg-abrechnung.js (plattform/api/eg_abrechnung.py)
9	//   WP5 Gründung   backend/demo/eg-gruendung.js  · backend/frappe/eg-gruendung.js  (plattform/api/eg_gruendung.py)
10	//   WP6 Portale    backend/demo/eg-portal.js     · backend/frappe/eg-portal.js     (plattform/api/eg_portal.py)
11	// Vertrag (Signaturen, Rückgaben, Rechte): docs/EG-SCHNITTSTELLEN.md und docs/API.md, Abschnitt „Energiegemeinschaften“.
12	// Datenmodell: src/lib/plattform/eg/modell.js. Diese Datei pflegt WP1; andere Pakete ändern nur ihre Zeile in EG_OPERATIONEN
13	// per Patch (docs/eg/<paket>.md).
14	//
15	// Auswahl wie backend(): Frappe bei PLATTFORM_BACKEND=frappe, sonst Demo (503 im Produktions-Build ohne PLATTFORM_DEMO=1).
16	// n = angemeldeter Nutzer (aus route()/portalNutzer), SYSTEM-Aufrufe (Scheduler, Ereignisse) mit egSystem().
17	// Nur serverseitig verwenden.
18	
19	import * as demoStamm from "./demo/eg-stamm";
20	import * as demoEda from "./demo/eg-eda";
21	import * as demoEnergie from "./demo/eg-energie";
22	import * as demoAbrechnung from "./demo/eg-abrechnung";
23	import * as demoGruendung from "./demo/eg-gruendung";
24	import * as demoPortal from "./demo/eg-portal";
25	import * as frappeStamm from "./frappe/eg-stamm";
26	import * as frappeEda from "./frappe/eg-eda";
27	import * as frappeEnergie from "./frappe/eg-energie";
28	import * as frappeAbrechnung from "./frappe/eg-abrechnung";
29	import * as frappeGruendung from "./frappe/eg-gruendung";
