35	/**
36	 * Operationen je Paket (Signaturen: docs/EG-SCHNITTSTELLEN.md, Abschnitt 4).
37	 *
38	 * WP1 Stamm (Lesen für alle Pakete, Schreiben Stammdaten):
39	 *   egKontext(n,{gemeinschaftId?}) → {gemeinschaften:[{id,name,modell,status,rollen[]}]}  Rollen des Kontos je Gemeinschaft
40	 *   egGemeinschaften(n,{status?,modell?,q?}) → {gemeinschaften[], kennzahlen, darfSchreiben}   Backoffice-Liste mit Kennzahlen
41	 *   egGemeinschaft(n,id) → {gemeinschaft, organe[], mitglieder[], zaehlpunkte[], teilnahmen[], anlagen[], tarife[], verteilschluessel[], netzbetreiber[], rollen[], rechte{}, hinweise[]}
42	 *   egGemeinschaftSpeichern(n,{id?,daten}) → gemeinschaft          egGemeinschaftStatus(n,id,{nach,grund?}) → gemeinschaft
43	 *   egOrganSpeichern(n,{gemeinschaftId,id?,daten}) → organ         egOrganBeenden(n,id,{bis}) → organ
44	 *   egMitgliedSpeichern(n,{gemeinschaftId,id?,daten}) → mitglied   egMitgliedStatus(n,id,{nach,grund?,zum?}) → mitglied
45	 *   egZaehlpunktSpeichern(n,{gemeinschaftId,id?,daten}) → zaehlpunkt
46	 *   egTeilnahmeSpeichern(n,{gemeinschaftId,id?,daten}) → teilnahme   (nur Entwurf bzw. TF-Wunsch; Status nur per Übergang)
47	 *   egTeilnahmeUebergang(n,teilnahmeId,{ereignis,datum?,consentId?,teilnahmefaktor?,responsecode?,prozessId?,grund?}) → teilnahme
48	 *   egAnlageSpeichern(n,{gemeinschaftId,id?,daten}) → anlage       egTarifSpeichern(n,{gemeinschaftId,id?,daten}) → tarif
49	 *   egVerteilschluesselSpeichern(n,{gemeinschaftId,id?,daten}) → verteilschluessel
50	 *   egMassenaktion(n,gemeinschaftId,{aktion,ids[],werte{}}) → {geaendert, fehler[]}
51	 *   egCsvImport(n,gemeinschaftId,{art,csv,ausfuehren}) → {vorschau[], fehler[], angelegt, geaendert}
52	 *   egCsvExport(n,gemeinschaftId,{art}) → {dateiname, csv}
53	 *   egNetzbetreiber(n) → {netzbetreiber[]}                         egNetzentgeltRegeln(n,{stichtag?}) → {regeln[]}
54	 *   egVerwaltung(n,gemeinschaftId) → Organe-Sicht (Vorstand/Kassier/Schriftführung/Rechnungsprüfung)
55	 *   egMigrationVorschau(n) · egMigrationAusfuehren(n) → {gemeinschaften, mitglieder, zaehlpunkte, teilnahmen, warnungen[]}
56	 * WP2 EDA:
57	 *   edaProzesse(n,gemeinschaftId,{status?,code?}) · edaProzess(n,id) · edaAnmelden(n,gemeinschaftId,{teilnahmeIds[],offline?})
58	 *   edaTfAendern(n,gemeinschaftId,{aenderungen:[{teilnahmeId,teilnahmefaktor,ab}]}) · edaAbmelden(n,gemeinschaftId,{teilnahmeIds[],zum})
59	 *   edaVerteilschluesselSenden(n,verteilschluesselId) · edaPodlistAnfordern(n,gemeinschaftId) · edaNachforderung(n,{zaehlpunktId,von,bis})
60	 *   edaNachrichtEingang(sys,{xml,quelle}) · edaFristenLauf(sys) · edaGemeinschaftBereit(sys,{gemeinschaftId})
61	 * WP3 Energie:
62	 *   enMessreihen(n,{gemeinschaftId,zaehlpunktId?,von,bis,groessen?}) · enEnergiedatenEmpfangen(sys,payload)
63	 *   enPeriodenwerte(n,gemeinschaftId,von,bis) → {zaehlpunkte:[{zaehlpunktId,teilnahmeId,groessen{groesse:kWh},vollstaendig,anteilL3}]}
64	 *   enQualitaet(n,gemeinschaftId,{monat}) · enAbweichungsbericht(n,gemeinschaftId,{monat}) · enCsvImport(n,gemeinschaftId,{csv})
65	 *   enSimulation(n,{daten}) · enSimulationen(n,{gemeinschaftId?}) · enPrognose(n,gemeinschaftId) · enOptimierung(n,{zaehlpunktId})
66	 * WP4 Abrechnung:
67	 *   abPerioden(n,gemeinschaftId) · abPeriodeAnlegen(n,gemeinschaftId,{von,bis,art}) · abPeriodeAktion(n,id,{aktion,…})
68	 *   abBelege(n,{gemeinschaftId?,mitgliedId?,periodeId?}) · abBelegPdf(n,id) · abZahlungslauf(n,gemeinschaftId,{art,belegIds[]})
69	 *   abCamtImport(n,gemeinschaftId,{xml}) · abMahnlauf(n,gemeinschaftId) · abBuchungen(n,gemeinschaftId,{jahr})
70	 *   abExport(n,gemeinschaftId,{art,jahr}) · abKleinunternehmer(n,gemeinschaftId) · abJahresbescheinigung(n,mitgliedId,{jahr})
71	 * WP5 Gründung:
72	 *   grAuftraege(n) · grAuftrag(n,id) · grAuftragAnlegen(n,{daten}) · grAuftragAktion(n,id,{aktion,…}) · grSchrittAktion(n,id,{schritt,aktion,…})
73	 *   grDokumentErzeugen(n,{gemeinschaftId,vorlage,daten}) · grImportVorschau(n,gemeinschaftId,{csv}) · grImportAusfuehren(n,importId)
74	 *   grFoerdercheck(n,{gemeinschaftId?,daten}) · grVersammlungen(n,gemeinschaftId) · grAufloesung(n,gemeinschaftId,{aktion})
75	 * WP6 Portale:
76	 *   ptUebersicht(n) · ptGemeinschaft(n,gemeinschaftId) · ptBeitrittAntrag(n,gemeinschaftId,{daten},{ip}) · ptKuendigung(n,mitgliedId,{zum})
77	 *   ptTfWunsch(n,teilnahmeId,{teilnahmefaktor}) · ptInteresse(null|n,{daten},{ip}) · ptGemeindeSicht(n) · ptDatenauskunft(n)
78	 *   ptRechner(null,{daten}) (öffentlich, ohne Personendaten) · ptBelege(n) · ptEnergie(n,{zaehlpunktId,von,bis})
79	 */
80	export const EG_OPERATIONEN = {
81	  stamm: [
82	    "egKontext", "egGemeinschaften", "egGemeinschaft", "egGemeinschaftSpeichern", "egGemeinschaftStatus", "egOrganSpeichern", "egOrganBeenden",
83	    "egMitgliedSpeichern", "egMitgliedStatus", "egZaehlpunktSpeichern", "egTeilnahmeSpeichern", "egTeilnahmeUebergang", "egAnlageSpeichern",
84	    "egTarifSpeichern", "egVerteilschluesselSpeichern", "egMassenaktion", "egCsvImport", "egCsvExport", "egNetzbetreiber", "egNetzentgeltRegeln",
85	    "egVerwaltung", "egMigrationVorschau", "egMigrationAusfuehren",
86	  ],
87	  eda: ["edaProzesse", "edaProzess", "edaAnmelden", "edaTfAendern", "edaAbmelden", "edaVerteilschluesselSenden", "edaPodlistAnfordern", "edaNachforderung", "edaNachrichtEingang", "edaFristenLauf", "edaGemeinschaftBereit"],
88	  energie: ["enMessreihen", "enEnergiedatenEmpfangen", "enPeriodenwerte", "enQualitaet", "enAbweichungsbericht", "enCsvImport", "enSimulation", "enSimulationen", "enPrognose", "enOptimierung"],
89	  abrechnung: ["abPerioden", "abPeriodeAnlegen", "abPeriodeAktion", "abBelege", "abBelegPdf", "abZahlungslauf", "abCamtImport", "abMahnlauf", "abBuchungen", "abExport", "abKleinunternehmer", "abJahresbescheinigung"],
90	  gruendung: ["grAuftraege", "grAuftrag", "grAuftragAnlegen", "grAuftragAktion", "grSchrittAktion", "grDokumentErzeugen", "grImportVorschau", "grImportAusfuehren", "grFoerdercheck", "grVersammlungen", "grAufloesung"],
91	  portal: ["ptUebersicht", "ptGemeinschaft", "ptBeitrittAntrag", "ptKuendigung", "ptTfWunsch", "ptInteresse", "ptGemeindeSicht", "ptDatenauskunft", "ptRechner", "ptBelege", "ptEnergie"],
92	};
93	export const EG_ALLE_OPERATIONEN = Object.values(EG_OPERATIONEN).flat();
94	
95	const DEMO = { ...demoStamm, ...demoEda, ...demoEnergie, ...demoAbrechnung, ...demoGruendung, ...demoPortal };
96	const FRAPPE = { ...frappeStamm, ...frappeEda, ...frappeEnergie, ...frappeAbrechnung, ...frappeGruendung, ...frappePortal };
97	
98	if (process.env.NODE_ENV !== "production") {
99	  for (const [name, impl] of [["demo", DEMO], ["frappe", FRAPPE]]) {
100	    const fehlt = EG_ALLE_OPERATIONEN.filter((op) => typeof impl[op] !== "function");
101	    if (fehlt.length) console.warn(`[plattform] Energiegemeinschaften ${name}: fehlende Operationen ${fehlt.join(", ")}`);
102	  }
103	}
104	
105	/** Aktive Implementierung (alle Pakete) oder 503 */
106	export function egBackend() {
107	  const n = backendName();
108	  if (n === "frappe") return FRAPPE;
109	  if (n === "demo") return DEMO;
110	  throw new PlattformFehler(503, KONFIG_FEHLER);
111	}
112	
113	/** Systemkonto für Scheduler und Ereignisse (wirkt wie Backoffice-Leitung; Operationen protokollieren „System“) */
114	export const egSystem = () => ({ id: "system-eg", rollen: ["admin"], backofficeRollen: ["leitung"], system: true });
115	
116	/**
117	 * Ereignis an das zuständige Paket weiterreichen (modell.js EG_EREIGNISSE). Ohne Empfänger-Operation (nur Information)
118	 * → { zugestellt: false }. Fehler des Empfängers werden NICHT verschluckt (Absender entscheidet über Wiederholung).
119	 */
120	export async function egEreignisSenden(name, payload = {}) {
121	  const e = EG_EREIGNISSE[name];
122	  if (!e) throw new PlattformFehler(422, `Unbekanntes Ereignis „${name}“.`);
123	  if (!e.operation) return { zugestellt: false };
124	  const b = egBackend();
125	  return { zugestellt: true, ergebnis: await b[e.operation](egSystem(), payload) };
126	}
127	// src/lib/plattform/backend/demo/eg-eda.js
128	//
129	// STUB WP2 „EDA-Marktkommunikation“ (Demo-Backend) – angelegt von WP1 als Platzhalter, damit die Fassade
130	// backend/eg.js vollständig ist. WP2 ersetzt diese Datei vollständig durch die echte Implementierung (gleiche Exporte,
131	// Signaturen laut docs/EG-SCHNITTSTELLEN.md, Abschnitt 4). Bis dahin antwortet jede Operation mit 501.
