189	  egOrganSpeichern: "eg_stamm.organ_speichern",
190	  egOrganBeenden: "eg_stamm.organ_beenden",
191	  egMitgliedSpeichern: "eg_stamm.mitglied_speichern",
192	  egMitgliedStatus: "eg_stamm.mitglied_status",
193	  egZaehlpunktSpeichern: "eg_stamm.zaehlpunkt_speichern",
194	  egTeilnahmeSpeichern: "eg_stamm.teilnahme_speichern",
