303	 * @param {{nutzer:object, gemeinschaft:object, organe?:object[], mitglieder?:object[], heute:string}} k
304	 * @returns {{rollen:string[], backofficeStufe:number}}
305	 */
306	export function egRollen({ nutzer, gemeinschaft, organe = [], mitglieder = [], heute } = {}) {
307	  const rollen = new Set();
308	  let backofficeStufe = 0;
309	  if (!nutzer || !gemeinschaft) return { rollen: [], backofficeStufe };
310	  const gid = gemeinschaft.id;
311	  for (const o of organe) {
312	    if (o.gemeinschaftId === gid && o.kontoId && o.kontoId === nutzer.id && organWirksam(o, heute)) {
313	      const r = ORGAN_FUNKTIONEN[o.funktion]?.teamrolle;
314	      if (r) rollen.add(r);
315	    }
316	  }
317	  for (const m of mitglieder) {
318	    if (m.gemeinschaftId !== gid || !m.kontoId || m.kontoId !== nutzer.id) continue;
319	    if (MITGLIED_AKTIV.includes(m.status)) rollen.add(m.art === "gemeinde" ? "gemeinde" : "mitglied");
320	    else if (["interessent", "antrag", "geprueft"].includes(m.status)) rollen.add("interessent");
321	  }
322	  if (nutzer.rollen?.includes("admin") && darfLesen(nutzer, "eg")) {
323	    backofficeStufe = darfSchreiben(nutzer, "eg") ? 2 : 1;
324	    if (VOR_BETRIEB.includes(gemeinschaft.status) || !GEMEINSCHAFT_STATUS[gemeinschaft.status]) rollen.add("gruendung");
325	    if (gemeinschaft.dienstleistung?.aktiv) rollen.add("organisator");
326	  }
327	  return { rollen: R.filter((r) => rollen.has(r)), backofficeStufe };
328	}
