330	/** Stufe (0–2) eines Rollen-Kontexts für ein Recht; Backoffice-Rollen gedeckelt auf die Stufe im Bereich „eg“ */
331	export function egStufe(kontext, recht) {
332	  const z = EG_RECHTE[recht]?.rollen;
333	  if (!z || !kontext) return 0;
334	  const aus = (kontext.rollen || []).reduce((m, r) => Math.max(m, BACKOFFICE_ROLLEN.includes(r) ? Math.min(z[r] || 0, kontext.backofficeStufe || 0) : z[r] || 0), 0);
335	  return BACKOFFICE_PFLEGE.includes(recht) ? Math.max(aus, kontext.backofficeStufe || 0) : aus;
336	}
