411	/** Gemeinschaft: erlaubter Folgezustand? Wirft 409 sonst. Pflichtangaben je Ziel (ZVR/FN, Marktpartner-ID, Gemeinschafts-ID). */
412	export function gemeinschaftUebergang(g, nach, { grund = "" } = {}) {
413	  const von = g?.status || "interesse";
414	  if (!GEMEINSCHAFT_STATUS[nach]) throw fehler("Unbekannter Status der Gemeinschaft.", "status");
415	  if (von === nach) return { status: nach };
416	  if (!GEMEINSCHAFT_STATUS[von]?.naechste.includes(nach)) throw konfliktFehler(`Wechsel von „${GEMEINSCHAFT_STATUS[von]?.label || von}“ nach „${GEMEINSCHAFT_STATUS[nach].label}“ ist nicht vorgesehen.`);
417	  if (nach === "rechtsperson" && g.rechtsform !== "keine" && !(g.zvrZahl || g.firmenbuchnummer)) throw fehler("Für den Status „Rechtsperson“ bitte ZVR-Zahl bzw. Firmenbuchnummer eintragen.", "zvrZahl");
418	  if (nach === "marktpartner" && !g.marktpartnerId) throw fehler("Für den Status „Marktpartner“ bitte die Marktpartner-ID (ebUtilities) eintragen.", "marktpartnerId");
419	  if (nach === "vertrag_nb" && !g.gemeinschaftsId) throw fehler("Für den Status „Vertrag mit dem Netzbetreiber“ bitte die Gemeinschafts-ID eintragen.", "gemeinschaftsId");
420	  if (["aufgeloest", "in_aufloesung"].includes(nach) && !text(grund, 500)) throw fehler("Bitte den Beschluss bzw. Grund angeben.", "grund");
421	  return { status: nach };
422	}
