424	/** Mitglied: erlaubter Folgezustand; Kündigung braucht `zum`, Ausschluss/Ablehnung einen Grund */
425	export function mitgliedUebergang(m, nach, { grund = "", zum = "" } = {}) {
426	  const von = m?.status || "interessent";
427	  if (!MITGLIED_STATUS[nach]) throw fehler("Unbekannter Mitgliedsstatus.", "status");
428	  if (von === nach) return { status: nach };
429	  if (!MITGLIED_STATUS[von]?.naechste.includes(nach)) throw konfliktFehler(`Wechsel von „${MITGLIED_STATUS[von]?.label || von}“ nach „${MITGLIED_STATUS[nach].label}“ ist nicht vorgesehen.`);
430	  if (nach === "gekuendigt" && !datumPruefen(zum)) throw fehler("Bitte das Austrittsdatum (Kündigung zum) angeben.", "zum");
431	  if (["abgelehnt", "ausgeschlossen"].includes(nach) && !text(grund, 500)) throw fehler("Bitte einen Grund angeben.", "grund");
432	  return { status: nach, ...(nach === "gekuendigt" ? { austrittZum: datumPruefen(zum) } : {}) };
433	}
