435	/**
436	 * Teilnahme-Übergang anhand eines Ereignisses (TEILNAHME_STATUS[…].ereignisse).
437	 * @param {object} t Teilnahme (EgTeilnahme)
438	 * @param {string} ereignis z. B. senden, anforderung_econ, zustimmung_econ, abschluss_econ, tf_geaendert, cm_rev_sp, cm_rev_cus …
439	 * @param {{heute:string, datum?:string, consentId?:string, teilnahmefaktor?:number, responsecode?:string, prozessId?:string, grund?:string, von?:string|null}} o
440	 * @returns {object} neue Teilnahme (Kopie) mit Verlaufseintrag
441	 */
442	export function teilnahmeUebergang(t, ereignis, o = {}) {
443	  const von = t?.status || "entwurf";
444	  const ziel = TEILNAHME_STATUS[von]?.ereignisse?.[ereignis];
445	  if (!ziel) throw konfliktFehler(`Ereignis „${ereignis}“ ist im Status „${TEILNAHME_STATUS[von]?.label || von}“ nicht vorgesehen.`);
446	  const heute = tag(o.heute);
447	  const d = datumPruefen(o.datum) || heute;
448	  const neu = { ...t, status: ziel, tfHistorie: [...(t.tfHistorie || [])], verlauf: [...(t.verlauf || [])] };
449	  if (o.responsecode !== undefined) neu.responsecode = text(o.responsecode, 40);
450	  if (ereignis === "anforderung_econ") neu.fristBis = plusTage(d, ZUSTIMMUNG_FRIST_TAGE);
451	  if (ereignis === "zustimmung_econ") {
452	    neu.consentId = text(o.consentId, 80) || t.consentId || "";
453	    neu.fristBis = "";
454	  }
455	  if (ereignis === "abschluss_econ") {
456	    if (!datumPruefen(o.datum)) throw fehler("Für die Aktivierung bitte das Aktivierungsdatum laut ABSCHLUSS_ECON angeben.", "datum");
457	    neu.gueltigAb = d;
458	    neu.gueltigBis = "";
459	    neu.tfHistorie.push({ gueltigAb: d, tf: t.teilnahmefaktor, prozessId: text(o.prozessId, 40) });
460	  }
461	  if (ereignis === "tf_geaendert") {
462	    const tf = ganz(o.teilnahmefaktor, TF_MIN, TF_MAX);
463	    if (tf === null) throw fehler(`Der Teilnahmefaktor ist eine ganze Zahl von ${TF_MIN} bis ${TF_MAX} %.`, "teilnahmefaktor");
464	    if (neu.tfHistorie.some((h) => h.gueltigAb === d)) throw konfliktFehler("Je Gemeinschaft und Zählpunkt ist derzeit nur eine Änderung des Teilnahmefaktors pro Tag möglich.");
465	    neu.teilnahmefaktor = tf;
466	    neu.tfHistorie.push({ gueltigAb: d, tf, prozessId: text(o.prozessId, 40) });
467	  }
468	  if (ereignis === "cm_rev_sp") {
469	    if (d < heute) throw konfliktFehler("Eine Abmeldung ist nicht rückwirkend möglich (Prozessdatum frühestens heute).");
470	    neu.gueltigBis = d;
471	  }
472	  if (["abmeldung_ok", "cm_rev_cus", "cm_rev_imp"].includes(ereignis)) {
473	    neu.gueltigBis = ereignis === "abmeldung_ok" ? t.gueltigBis || d : d;
474	    neu.beendetGrund = ereignis === "cm_rev_cus" ? "widerruf" : ereignis === "cm_rev_imp" ? "implizit" : "abmeldung";
475	  }
476	  if (ereignis === "abmeldung_abgelehnt") neu.gueltigBis = "";
477	  if (ereignis === "erneut") Object.assign(neu, { consentId: "", fristBis: "", responsecode: "" });
478	  neu.verlauf.push({ am: o.am || `${heute}T12:00:00.000Z`, von, nach: ziel, ereignis, prozessId: text(o.prozessId, 40), text: text(o.grund, 300), vonKonto: o.von ?? null });
479	  return neu;
480	}
