function prozessLebt(pid) {
  if (!pid) return false;
  try {
    process.kill(pid, 0);
    return true;
  } catch (e) {
    return e.code === "EPERM";
  }
}

async function sperren() {
  await fs.mkdir(DATEN_ORDNER, { recursive: true });
