  fall("xml", "xmlSchreiben", [{ name: "A", attrs: { x: "1 & 2", y: '"q"' }, kinder: [{ name: "B", text: "<ä>" }, { name: "C" }, { name: "D", text: 5 }] }]);
  fall("xml", "xmlLesen", ['<?xml version="1.0"?><!-- k --><p:A xmlns:p="urn:x" a="1"><p:B>x &amp; y &#228;</p:B><C/><D><![CDATA[<roh>]]></D></p:A>']);
