  });
  const luecken = datenluecken({ teilnahmen: tl.filter((t) => t.gueltigAb && ["aktiv", "abmeldung_angefragt", "beendet"].includes(t.status)).map((t) => ({ teilnahmeId: t.id, zaehlpunktnummer: t.zaehlpunktnummer, gueltigAb: t.gueltigAb, gueltigBis: t.gueltigBis })), empfangen: empfangeneTage(db, g.id), von: plusTage(h, -14), bis: h, heute: h });
  const nbs = [...new Set([...(g.netzbetreiber || []), ...tl.map((t) => t.netzbetreiberId).filter(Boolean)])].map((id) => nbVon(db, id)).filter(Boolean);
