		return {"prozess": _ausgabe(offen), "bereitsOffen": True}
	p = _neuer_prozess(g, "EC_PODLIST", n, prozessdatum=_heute())
	_versenden(p, g)
	_proto(n, "eg_eda_podlist", g["id"], f"Zählpunktliste angefordert ({p['id']})")
	return {"prozess": _ausgabe(p)}


